import type { FilePlace } from "./FilePlace";
import type { Hunk } from "./Hunk";

/**
 * One file's cumulative change over the whole session: from how it was before the agent first
 * touched it to how it is now.
 */
export type FileChange = { 
/**
 * Relative to its working tree's top ([`FileChange::tree`]) when it's in one, else to the
 * session's directory when inside it.
 */
path: string, 
/**
 * The top of the git working tree it's in, when that's one of the session's repository's: its
 * folder's own, or a worktree of it the agent works in.
 */
tree?: string, created?: boolean, deleted?: boolean, added: number, removed: number, hunks: Array<Hunk>, 
/**
 * Too large (or binary) to show; counts only.
 */
truncated?: boolean, 
/**
 * Unix ms of the last change.
 */
at: number, 
/**
 * Who changed it, in the order they first did: the agent itself ([`BY_AGENT`]) or a subagent
 * run of its harness's, by its spawning call's id (as its events' [`Event::parent`] names it).
 * None from a runner that doesn't say.
 */
by?: Array<string>, 
/**
 * Whose it is: the Changes tab's scope shows this project's at first. None from a runner that
 * doesn't say: read as this project's, so it shows at every scope.
 */
place?: FilePlace, };
